"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The Shadow of the necromancer Sylas', 'author': 'Signature original', 'genre': 'Dark Lord Sagas', 'chapters': [{'n': 1, 'title': 'The Call', 'text': "They left Dragonpeak at dusk, the road winding into the unknown. Behind them, lights went out one by one as the necromancer Sylas's shadow spread. Ahead: everything.\n\nRowan Ember slept that night with the rune glowing faintly, and dreamed of Dragonpeak in flames. They woke with the taste of smoke and a single thought: unity defeats darkness.\n\nRowan Ember was mending a fence in Dragonpeak when the sky went dark at noon. The elders whispered: the necromancer Sylas had taken the Sword of Kings, and the old magic was failing. Prophecy or not, someone had to go."}, {'n': 2, 'title': 'Trials of the Road', 'text': "At the moonwell they met a seer who spoke of the Sword of Kings: 'It is not a weapon,' she said, 'though it can kill. It is not a shield, though it can save. It is a promise — and promises are the heaviest magic.'\n\nThey were ambushed by the necromancer Sylas's riders at the enchanted glade. Rowan Ember fought with a mithril blade borrowed from the dwarf Bram Ironhold, and learned that bravery is mostly refusing to run at the right moment.\n\nThe road through Dragonpeak tested them daily: a bridge held by a troll who demanded riddles, a forest where the trees walked, a river that flowed uphill. the dwarf Bram Ironhold's wit and Rowan Ember's courage saw them through each."}, {'n': 3, 'title': 'The Descent', 'text': "Alarms rang. the necromancer Sylas's army closed in. the dwarf Bram Ironhold barred the door with a fallen pillar and grinned. 'Go,' they said. 'I'll hold them.' Rowan Ember refused to leave — so they held it together, back to back, as the dark came on.\n\nThe dungeons held prisoners from every corner of Dragonpeak, and Rowan Ember freed them all, though it slowed the quest. 'the Sword of Kings can wait an hour,' Rowan Ember said. 'People cannot.' the dwarf Bram Ironhold never loved them more.\n\nthe Sword of Kings blazed at Rowan Ember's touch, recognizing its bearer. Power flooded through them — and with it, the terrible knowledge of its price. Every magic, the seer had said, is a promise. This one demanded everything."}, {'n': 4, 'title': 'The Price', 'text': "They marched on the necromancer Sylas's stronghold with the Sword of Kings dark but their hearts lit. Rowan Ember carried it anyway, empty as it was. Symbols, the dwarf Bram Ironhold said, have their own magic.\n\nThey escaped the fortress by griffon, the Sword of Kings burning like a small sun. But the dwarf Bram Ironhold was wounded, and the wound festered with dark magic. The healers said only the Sword of Kings itself could cure it — at the cost of its power.\n\nThen the freed prisoners arrived — an army of the grateful, farmers with pitchforks and smiths with hammers, all come to stand with the bearer of the Sword of Kings. Rowan Ember understood at last: the promise was never the crystal. It was this."}, {'n': 5, 'title': 'The Breaking of the Dark', 'text': "Rowan Ember fought with the mithril blade and no magic at all — only skill, and love of Dragonpeak, and the dwarf Bram Ironhold shouting from the lines. the necromancer Sylas fought with hate and sorcery, and for a long while hate seemed stronger.\n\nThe army of the dark broke and ran. Dragonpeak was free. Rowan Ember stood in the sudden silence holding the Sword of Kings, which was only a crystal again — but a crystal that had kept its promise.\n\nThen Rowan Ember remembered the seer's words and the dragon's riddle, and did the last thing the necromancer Sylas expected: Rowan Ember offered mercy. 'Yield,' Rowan Ember said, 'and live.' the necromancer Sylas laughed — and in that laugh, the dark wavered."}, {'n': 6, 'title': 'The Return', 'text': 'the Sword of Kings was set in the great hall, where children touch it for luck. It never blazed again — but on dark nights, travelers swear it glows faintly, like a coal that remembers fire.\n\nRowan Ember and the dwarf Bram Ironhold grew old telling the tale, arguing over every detail, and Dragonpeak prospered. The prophecy, the elders admitted, had never named a chosen one at all. It had named a choice.\n\nThey came home to Dragonpeak in spring, when the orchards bloomed. The songs had already arrived ahead of them, as songs do, and every verse was wrong in the details and right in the heart.'}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

